#include <bits/stdc++.h>
using namespace std;

class Solution {public:long long maximumImportance(int n,vector<vector<int>>& roads){vector<int> deg(n);for(auto &e:roads){++deg[e[0]];++deg[e[1]];}sort(deg.begin(),deg.end());long long ans=0;for(int i=0;i<n;++i)ans+=1LL*deg[i]*(i+1);return ans;} };
